function renderProjects(){if(!$('projectList'))grid.innerHTML=projectsMarkup();$('newProject').onclick=()=>openProject();$('newChapter').onclick=()=>openChapter();let q=$('search').value.trim(),rows=projects.filter(x=>!q||x.title.includes(q)||x.genre.includes(q));$('projectList').innerHTML=rows.length?rows.map(x=>`<div class="story-card"><span class="tags">${safe(x.status)} · ${safe(x.genre||'题材待定')}</span><h3>${safe(x.title)}</h3><p>${safe(x.logline||'故事一句话待补充')}</p><p><b>核心矛盾：</b>${safe(x.core_conflict||'待补充')}</p><div class="row-actions"><button onclick="selectProject('${x.id}')">章节卡</button><button onclick="editProject('${x.id}')">编辑</button><button onclick="removeProject('${x.id}')">删除</button></div></div>`).join(''):'<div class="empty">暂无故事项目，点击“故事项目”创建第一部作品。</div>';let selected=projects.find(x=>x.id===selectedProjectId);$('chapterPanelTitle').textContent=selected?`《${selected.title}》章节节奏卡`:'章节节奏卡';$('newChapter').disabled=!selected;$('chapterList').innerHTML=!selected?'<div class="empty">选择一个故事项目后管理章节卡。</div>':chapters.filter(x=>x.project_id===selected.id).map(x=>`<div class="chapter-card"><span class="hook">第 ${x.chapter_no} 章 · ${safe(x.opening_hook||'开篇钩子待补充')}</span><h3>${safe(x.title)}</h3><p class="muted">${safe(x.objective||'本章目标待补充')}</p><div class="beats"><div class="beat"><b>起</b><br>${safe(x.beat_qi||'待补充')}</div><div class="beat"><b>承</b><br>${safe(x.beat_cheng||'待补充')}</div><div class="beat"><b>转</b><br>${safe(x.beat_zhuan||'待补充')}</div><div class="beat"><b>合</b><br>${safe(x.beat_he||'待补充')}</div></div><div class="tags">章尾钩子：${safe(x.ending_hook||'待补充')} · 情绪：${safe(x.emotion_curve||'待补充')}</div><div class="row-actions"><button onclick="editChapter('${x.id}')">编辑</button><button onclick="removeChapter('${x.id}')">删除</button></div></div>`).join('')||'<div class="empty">暂无章节卡，点击“章节卡”开始拆分节奏。</div>'}
