let templates=[],templateEditing=null;nav[5].dataset.view='templates';nav[5].querySelector('em').id='templateCount';document.head.insertAdjacentHTML('beforeend',`<style>.template-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:12px}.template-card{padding:16px;border:1px solid var(--line);border-radius:10px;background:#151821}.template-card h3{margin:5px 0}.template-card p{color:var(--muted);font-size:12px}.template-block{margin-top:9px;padding:9px;border-radius:7px;background:#0e1017;white-space:pre-wrap;font-size:11px;color:#bbc0ce}.validated{color:#34d399}.draft{color:#fbbf24}</style>`);document.body.insertAdjacentHTML('beforeend',`<div class="modal-wrap" id="templateModal"><form class="modal" id="templateForm"><div class="modal-head"><h2 id="templateFormTitle">新建创作 SOP</h2><button type="button" class="close" id="templateClose">×</button></div><input class="field" id="templateName" required placeholder="模板名称：暗黑玄幻副本设计 SOP"><select class="field" id="templateCategory"><option>爆款开头</option><option>人物设计</option><option>世界规则</option><option>副本设计</option><option>章节节奏</option><option>连续性质检</option><option>改写润色</option></select><textarea class="field" id="templatePurpose" placeholder="适用场景与解决的问题"></textarea><textarea class="field" id="templateInputs" placeholder="输入要求：使用前必须准备哪些素材"></textarea><textarea class="field" id="templateSteps" placeholder="执行步骤：每行一步，写清判断标准"></textarea><textarea class="field" id="templateOutputs" placeholder="输出格式：最终应生成哪些字段"></textarea><textarea class="field" id="templateChecklist" placeholder="质检清单：什么情况算通过"></textarea><select class="field" id="templateStatus"><option>草稿</option><option>测试中</option><option>已验证</option></select><button class="btn" type="submit">保存 SOP</button><div class="error" id="templateError"></div></form></div>`);
loadAll=async function(){let [ir,ar,cr,rr,pr,hr,tr]=await Promise.all([db.from('ideas').select('*').order('created_at',{ascending:false}),db.from('assets').select('*').order('created_at',{ascending:false}),db.from('characters').select('*').order('created_at',{ascending:false}),db.from('relationships').select('*').order('created_at',{ascending:false}),db.from('story_projects').select('*').order('created_at',{ascending:false}),db.from('chapter_cards').select('*').order('chapter_no',{ascending:true}),db.from('sop_templates').select('*').order('created_at',{ascending:false})]);let err=ir.error||ar.error||cr.error||rr.error||pr.error||hr.error||tr.error;if(err){const target=$('list')||$('assetList')||$('peopleList')||$('projectList')||$('templateList');if(target)target.innerHTML=`<div class="empty">读取失败：${safe(err.message)}</div>`;return}ideas=ir.data||[];assets=ar.data||[];characters=cr.data||[];relationships=rr.data||[];projects=pr.data||[];chapters=hr.data||[];templates=tr.data||[];renderCurrent()};
