function renderTemplates(){if(!$('templateList'))grid.innerHTML=templatesMarkup();$('newTemplate').onclick=()=>openTemplate();bindChips();let q=$('search').value.trim(),rows=templates.filter(x=>(filter==='全部'||x.category===filter)&&(!q||x.name.includes(q)||x.purpose.includes(q)));$('templateList').innerHTML=rows.length?rows.map(x=>`<div class="template-card"><span class="${x.status==='已验证'?'validated':'draft'}">${safe(x.status)} · ${safe(x.category)}</span><h3>${safe(x.name)}</h3><p>${safe(x.purpose||'适用场景待补充')}</p><div class="template-block"><b>输入</b>\n${safe(x.inputs||'待补充')}\n\n<b>步骤</b>\n${safe(x.steps||'待补充')}\n\n<b>质检</b>\n${safe(x.checklist||'待补充')}</div><div class="row-actions"><button onclick="editTemplate('${x.id}')">编辑</button><button onclick="removeTemplate('${x.id}')">删除</button></div></div>`).join(''):'<div class="empty">暂无创作 SOP。把一次有效的创作方法沉淀成可重复执行的模板。</div>'}
