function firstSummary(text){return (text||'').split(/\n+/).map(x=>x.trim()).find(Boolean)?.slice(0,100)||''}
function sectionOf(text,label){let labels=['开篇钩子','起','承','转','合','章尾钩子','情绪曲线','连续性检查','适用场景','输入要求','执行步骤','输出格式','质检清单'],lines=(text||'').split('\n'),start=lines.findIndex(x=>new RegExp(`^\\s*(?:[#*\\-]+\\s*)?${label}[：:]`).test(x));if(start<0)return '';let first=lines[start].replace(new RegExp(`^\\s*(?:[#*\\-]+\\s*)?${label}[：:]\\s*`),'').trim(),out=first?[first]:[];for(let i=start+1;i<lines.length;i++){if(labels.some(k=>new RegExp(`^\\s*(?:[#*\\-]+\\s*)?${k}[：:]`).test(lines[i])))break;out.push(lines[i])}return out.join('\n').trim()}
