function dashboardMarkup(){return `<section class="dashboard-grid" style="grid-column:1/-1"><article class="panel"><div class="eyebrow">SYSTEM HEALTH</div><h2>工作资料库健康度</h2><div class="health-wrap"><div class="health-ring" id="healthRing"><strong id="healthScore">0</strong></div><div class="check-list" id="healthChecks"></div></div></article><article class="panel"><div class="eyebrow">NEXT ACTIONS</div><h2>现在最值得处理</h2><div class="todo-list" id="todoList"></div></article><article class="panel dashboard-wide"><div class="story-toolbar"><div><span class="eyebrow">RECENT ACTIVITY</span><h2>最近产出</h2></div></div><div class="recent-list" id="recentList"></div></article><article class="panel dashboard-wide"><div class="backup-box"><div><span class="eyebrow">DATA BACKUP</span><h2>完整数据备份</h2><p>下载当前账号的全部内容数据。备份文件不包含密码和数据库密钥。</p></div><button class="btn" id="exportBackup">导出 JSON 备份</button></div></article></section>`}
function dashboardChecks(){return [{ok:assets.some(x=>x.status==='已确认'),text:'已有可调用的已确认资产'},{ok:characters.length>0&&relationships.length>0,text:'人物卡与关系网已建立'},{ok:projects.length>0&&chapters.length>0,text:'故事项目已有章节节奏卡'},{ok:templates.some(x=>x.status==='已验证'),text:'至少一份 SOP 已验证'},{ok:pipelines.some(x=>x.status==='已完成')&&conversions.length>0,text:'流水线结果已完成闭环入库'}]}
function dashboardTodos(){let noChapters=projects.filter(p=>!chapters.some(c=>c.project_id===p.id)).length,items=[{n:ideas.filter(x=>x.status==='待加工').length,label:'条灵感等待加工',view:'ideas'},{n:assets.filter(x=>x.status==='待确认').length,label:'张资产卡等待确认',view:'assets'},{n:pipelines.filter(x=>x.status==='待审核').length,label:'条流水线结果等待审核',view:'pipelines'},{n:noChapters,label:'个故事项目还没有章节卡',view:'projects'},{n:templates.filter(x=>x.status!=='已验证').length,label:'份 SOP 尚未验证',view:'templates'}];return items.filter(x=>x.n>0)}
function recentItems(){let all=[...ideas.map(x=>({kind:'灵感',title:x.title,status:x.status,date:x.updated_at||x.created_at,view:'ideas'})),...assets.map(x=>({kind:x.asset_type,title:x.title,status:x.status,date:x.updated_at||x.created_at,view:'assets'})),...characters.map(x=>({kind:'人物',title:x.name,status:x.role||'人物卡',date:x.updated_at||x.created_at,view:'relations'})),...projects.map(x=>({kind:'项目',title:x.title,status:x.status,date:x.updated_at||x.created_at,view:'projects'})),...templates.map(x=>({kind:'SOP',title:x.name,status:x.status,date:x.updated_at||x.created_at,view:'templates'})),...pipelines.map(x=>({kind:'流水线',title:x.name,status:x.status,date:x.updated_at||x.created_at,view:'pipelines'}))];return all.filter(x=>x.date).sort((a,b)=>new Date(b.date)-new Date(a.date)).slice(0,8)}
function renderDashboard(){if(!$('healthChecks'))grid.innerHTML=dashboardMarkup();let checks=dashboardChecks(),score=checks.filter(x=>x.ok).length*20;$('healthScore').textContent=score;$('healthRing').style.setProperty('--health',score+'%');$('healthChecks').innerHTML=checks.map(x=>`<div class="health-check ${x.ok?'ok':'warn'}">${x.ok?'✓':'○'} ${safe(x.text)}</div>`).join('');let todos=dashboardTodos();$('todoList').innerHTML=todos.length?todos.map(x=>`<div class="todo-row"><span><b>${x.n}</b> ${safe(x.label)}</span><button onclick="switchView('${x.view}')">去处理</button></div>`).join(''):'<div class="empty">当前没有待处理项，可以开始新的市场扫描或故事开发。</div>';let recent=recentItems();$('recentList').innerHTML=recent.length?recent.map(x=>`<div class="recent-row"><span class="tags">${safe(x.kind)}</span><strong>${safe(x.title)}</strong><span class="muted">${safe(x.status)} · ${new Date(x.date).toLocaleDateString('zh-CN')}</span></div>`).join(''):'<div class="empty">还没有内容资产，先录入第一条灵感。</div>';$('exportBackup').onclick=exportBackup}
